package lt.viko.eif.imazolevska.jaxws_client.config;

import jakarta.xml.ws.BindingProvider;
import lt.viko.eif.imazolevska.jaxws.client.DirectorService;
import lt.viko.eif.imazolevska.jaxws.client.DirectorServiceImplService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Creates the SOAP client generated by wsimport as a Spring bean,
 * so other classes depend only on the {@link DirectorService} interface.
 */
@Configuration
public class PortConfiguration {

    /**
     * Creates the SOAP client and points it to the configured service address.
     *
     * @param url address of the SOAP service, taken from {@code directors.service.url}
     * @return client that sends SOAP requests to the server
     */

    @Bean
    public DirectorService directorSoapClient(@Value("${directors.service.url}") String url) {
        DirectorService port = new DirectorServiceImplService().getDirectorServiceImplPort();
        ((BindingProvider) port).getRequestContext().put(BindingProvider.ENDPOINT_ADDRESS_PROPERTY, url);
        return port;
    }

}
